CREATE TABLE rooms (id uuid PRIMARY KEY, name text NOT NULL CHECK(length(name) BETWEEN 1 AND 80), host_account_id uuid NOT NULL REFERENCES accounts(id), state text NOT NULL CHECK(state IN ('waiting','preparing','loading','running','suspended','ended')), revision integer NOT NULL DEFAULT 1 CHECK(revision>0), config_revision integer NOT NULL DEFAULT 1 CHECK(config_revision>0), config jsonb NOT NULL, current_run_id uuid);
CREATE TABLE memberships (desktop_id uuid PRIMARY KEY REFERENCES sessions(id), room_id uuid NOT NULL REFERENCES rooms(id), account_id uuid NOT NULL REFERENCES accounts(id), presence_until timestamptz, ready_config_revision integer, selected boolean NOT NULL DEFAULT false);
CREATE INDEX room_members ON memberships(room_id);
CREATE TABLE runs (id uuid PRIMARY KEY, room_id uuid NOT NULL REFERENCES rooms(id), epoch uuid NOT NULL, service_epoch uuid NOT NULL, config_revision integer NOT NULL, config jsonb NOT NULL, roster uuid[] NOT NULL, state text NOT NULL CHECK(state IN ('preparing','loading','running','suspended','cancelled','ended')), preparation_until timestamptz NOT NULL, created_at timestamptz NOT NULL, ended_at timestamptz, reason text);
ALTER TABLE rooms ADD CONSTRAINT current_run FOREIGN KEY(current_run_id) REFERENCES runs(id);
CREATE INDEX run_room ON runs(room_id);
CREATE TABLE attachments (id uuid PRIMARY KEY, run_id uuid NOT NULL REFERENCES runs(id), desktop_id uuid NOT NULL REFERENCES sessions(id), game_session_id uuid NOT NULL UNIQUE REFERENCES sessions(id), game_instance_id text NOT NULL, service_epoch uuid NOT NULL, run_epoch uuid NOT NULL, config_revision integer NOT NULL, seed_applied boolean NOT NULL DEFAULT false, loaded boolean NOT NULL DEFAULT false, presence_until timestamptz NOT NULL, resume_until timestamptz NOT NULL, revoked_at timestamptz, UNIQUE(run_id,desktop_id));
CREATE TABLE command_results (scope uuid NOT NULL REFERENCES sessions(id), request_id text NOT NULL, fingerprint text NOT NULL, result jsonb NOT NULL, created_at timestamptz NOT NULL, PRIMARY KEY(scope,request_id));
